import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const html=fs.readFileSync(new URL('../arcade.html',import.meta.url),'utf8');
const context=vm.createContext({});
vm.runInContext(html.match(/<script id="engine">([\s\S]*?)<\/script>/)[1]+';globalThis.Game=Game;',context);
const make=()=>new context.Game(()=>0.42);
const empty=()=>Array.from({length:20},()=>Array(10).fill(null));
const piece=(type,m,x,y)=>({type,m,x,y});
test('seven-bag deals each shape once; reset restores the entire run',()=>{
 const g=make(),types=[];
 for(let i=0;i<14;i++){types.push(g.piece.type);g.spawn();}
 assert.equal(new Set(types.slice(0,7)).size,7);assert.equal(new Set(types.slice(7)).size,7);
 g.score=90;g.lines=14;g.held='T';g.over=true;g.reset();
 assert.equal(g.score,0);assert.equal(g.lines,0);assert.equal(g.level,1);assert.equal(g.held,null);assert.equal(g.over,false);
 assert.ok(g.board.every(r=>r.every(v=>v===null)));assert.equal(g.queue.length,5);
});
test('movement respects walls, floor and occupied cells without corrupting pieces',()=>{
 const g=make();g.piece=piece('O',[[1,1],[1,1]],0,18);
 assert.equal(g.move(-1,0),false);assert.equal(g.move(0,1),false);assert.equal(g.move(1,0),true);
 g.board[18][3]='T';assert.equal(g.move(1,0),false);assert.equal(g.piece.x,1);
});
test('four clockwise rotations restore a piece; counterclockwise reverses rotation',()=>{
 const g=make();g.spawn('T');const initial=JSON.stringify(g.piece);
 for(let i=0;i<4;i++)assert.equal(g.rotate(),true);
 assert.equal(JSON.stringify(g.piece),initial);g.rotate();g.rotate(-1);assert.equal(JSON.stringify(g.piece),initial);
});
test('rotation kicks away from a wall and floor; blocked rotation is a no-op',()=>{
 const g=make();g.spawn('I');g.rotate();g.piece.x=-2;assert.equal(g.valid(g.piece),true);assert.equal(g.rotate(),true);assert.equal(g.valid(g.piece),true);
 g.board=empty();g.piece=piece('T',[[0,1,0],[1,1,1],[0,0,0]],3,18);assert.equal(g.rotate(),true);assert.equal(g.valid(g.piece),true);
 g.board=Array.from({length:20},()=>Array(10).fill('O'));g.piece=piece('T',[[0,1,0],[1,1,1],[0,0,0]],3,5);
 g.piece.m.forEach((r,y)=>r.forEach((v,x)=>{if(v)g.board[y+5][x+3]=null;}));
 const before=JSON.stringify(g.piece);assert.equal(g.rotate(),false);assert.equal(JSON.stringify(g.piece),before);
});
test('ghost and hard drop agree, award distance points and lock exactly four cells',()=>{
 const g=make();g.spawn('O');const y=g.ghostY();assert.equal(y,18);assert.equal(g.piece.y,0);
 const result=g.hardDrop();assert.equal(result.cleared,0);assert.equal(g.score,36);assert.equal(g.board.flat().filter(Boolean).length,4);
 assert.equal(g.board[18][4],'O');assert.equal(g.board[19][5],'O');
});
test('soft drop scores only successful movement',()=>{
 const g=make();g.spawn('O');assert.equal(g.softDrop(),true);assert.equal(g.score,1);g.piece.y=18;assert.equal(g.softDrop(),false);assert.equal(g.score,1);
});
test('one through four completed rows clear, compact and award the expected score',()=>{
 for(let n=1;n<=4;n++){
  const g=make();g.board=empty();for(let y=20-n;y<20;y++){g.board[y].fill('J');g.board[y][4]=null;}
  g.piece=piece('I',[[1],[1],[1],[1]],4,16);g.board[10][0]='S';
  const result=g.lock();assert.equal(result.cleared,n);assert.equal(g.score,[0,100,300,500,800][n]);assert.equal(g.lines,n);
  assert.equal(g.board.length,20);assert.equal(g.board[10+n][0],'S');assert.ok(g.board.every(r=>r.length===10));
 }
});
test('levels advance each ten lines and successive clears receive a combo bonus',()=>{
 const g=make();g.lines=9;
 function clear(){g.board=empty();g.board[19].fill('T');g.board[19][4]=null;g.piece=piece('I',[[1],[1],[1],[1]],4,16);return g.lock();}
 assert.equal(clear().gain,100);assert.equal(g.level,2);assert.equal(clear().gain,300);assert.equal(g.combo,1);
 g.board=empty();g.hardDrop();assert.equal(g.combo,-1);
});
test('hold is limited to once per piece, resets on landing and swaps without consuming queue',()=>{
 const g=make(),first=g.piece.type,next=g.queue[0];assert.equal(g.hold(),true);assert.equal(g.held,first);assert.equal(g.piece.type,next);assert.equal(g.hold(),false);
 g.hardDrop();const queue=JSON.stringify(g.queue),current=g.piece.type;assert.equal(g.hold(),true);assert.equal(g.piece.type,first);assert.equal(g.held,current);assert.equal(JSON.stringify(g.queue),queue);assert.equal(g.piece.y,0);
});
test('spawn collision causes game over and prevents subsequent gameplay mutations',()=>{
 const g=make();g.board[0].fill('O');g.board[1].fill('O');g.spawn('O');assert.equal(g.over,true);
 const snapshot=JSON.stringify(g);assert.equal(g.move(1,0),false);assert.equal(g.rotate(),false);assert.equal(g.hold(),false);assert.equal(g.hardDrop(),null);assert.equal(JSON.stringify(g),snapshot);
});
test('many seeded runs preserve legal active pieces and board dimensions',()=>{
 let seed=71;const random=()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};
 for(let run=0;run<30;run++){
  const g=new context.Game(random);for(let i=0;i<120&&!g.over;i++){
   for(let j=0;j<4;j++){g.rotate(random()<.5?1:-1);g.move(random()<.5?-1:1,0);}
   assert.ok(g.valid(g.piece));g.hardDrop();assert.equal(g.board.length,20);assert.ok(g.board.every(r=>r.length===10));
  }
 }
});

